        WordPack(id: "hard", title: "Сложное", subtitle: "Для любителей вызовов", symbol: "bolt", words: words("Парадокс | Ностальгия | Бюрократия | Альтруизм | Инерция | Эмпатия | Энтропия | Консенсус | Ирония | Абстракция | Детерминизм | Метаморфоза | Антитеза | Прагматизм | Ренессанс | Конформизм | Харизма | Эйфория | Диссонанс | Сублимация | Скептицизм | Эвфемизм | Дилемма | Синергия | Утопия | Риторика | Стоицизм | Монополия | Легитимность | Эклектика | Сарказм | Меланхолия | Анахронизм | Плюрализм | Стереотип | Иерархия | Идентичность | Метафора | Кульминация | Самоирония | Антагонизм | Рациональность | Инфляция | Предубеждение | Прецедент | Аксиома | Рефлексия | Резонанс | Эскапизм | Перфекционизм")),
        WordPack(id: "roulette", title: "Рулетка", subtitle: "Всё вперемешку", symbol: "shuffle", words: []),
        WordPack(id: "phrases", title: "Словосочетания", subtitle: "Объясни целую фразу", symbol: "text.bubble", words: words("Замкнутый круг | Тайный поклонник | Белая ворона | Золотая середина | Ледниковый период | Точка невозврата | Воздушный замок | Сарафанное радио | Чёрная дыра | Морская болезнь | Солнечный зайчик | Ночной дозор | Кошачий глаз | Медвежья услуга | Камень преткновения | Мыльный пузырь | Сила привычки | Птичье молоко | Порочный круг | Северное сияние | Машина времени | Закон подлости | Ход конём | Звёздный час | Тихий океан | Круглый стол | Живая очередь | Вечный двигатель | Чувство юмора | Личная жизнь | Падающая звезда | Обратная связь | Ложная тревога | Запасной выход | Зона комфорта | Чистый лист | Спящий город | Второе дыхание | Снежный человек | Рабочее настроение | Культурный шок | Почтовый голубь | Пищевая цепочка | Слепое пятно | Горячая линия | Сладкая вата | Домашний арест | Дальний свет | Золотые руки | Светлая голова")),
        WordPack(id: "developers", title: "Программисты", subtitle: "От бага до релиза", symbol: "chevron.left.forwardslash.chevron.right", words: words("Рекурсия | Дедлок | Код-ревью | Компилятор | Баг | Сервер | База данных | Массив | Наследование | Полиморфизм | Инкапсуляция | Протокол | Интерфейс | Фреймворк | Алгоритм | Хеш-таблица | Указатель | Деплой | Коммит | Мёрдж-конфликт | Репозиторий | Отладчик | Кеш | Микросервис | Рефакторинг | Синглтон | Юнит-тест | Поток | Асинхронность | Замыкание | Опционал | Сборщик мусора | Утечка памяти | Стек | Очередь | Бинарное дерево | Контейнер | Сокет | Порт | Авторизация | Шифрование | Паттерн | Парсер | Логирование | Зависимость | Пакет | Виртуальная машина | Верстка | Пул-реквест | Технический долг"))
    ]
    static func deck(from packs: [WordPack]) -> [String] {
        let selected = packs.contains { $0.id == "roulette" } ? packs + all.filter { $0.id != "roulette" } : packs
        return Array(Set(selected.flatMap(\.words).map { $0.trimmingCharacters(in: .whitespacesAndNewlines) }.filter { !$0.isEmpty })).shuffled()
    }
}
